  cp=run/'etc'/(role+'.toml'); row['configs'][role]=cp.read_text() if cp.exists() else None
  lp=run/'log'/(role+'.log'); row['log_tails'][role]=lp.read_text().splitlines()[-20:] if lp.exists() else []
 rows[tag]=row
print(json.dumps({'time_unix_ms':int(time.time()*1000),'runs':rows,'uptime':pathlib.Path('/proc/uptime').read_text()},indent=2))

